{
  "hypothesis": "Small-cap stocks showing abnormally high volume are likely to underperform in the following days due to retail-driven overbuying and subsequent mean reversion.",
  "factors": [
    {
      "name": "vol_reversal_depth",
      "expression": "TS_ARGMAX(TS_ZSCORE(RANK($volume), 20), 5) - TS_ARGMIN(TS_ZSCORE(RANK($return), 20), 5)",
      "explanation": "Measures the difference between the top and bottom volume-return extremes, exploring depth of reversal patterns"
    },
    {
      "name": "vol_corr_rank",
      "expression": "RANK(TS_CORR($close, $volume, 10)) * RANK($return, 30)",
      "explanation": "Combines correlation between price and volume with return ranking, exploring unusual pairing of variables"
    },
    {
      "name": "vol_timescale_ratio",
      "expression": "TS_RSI($volume, 5) / TS_RSI($volume, 20)",
      "explanation": "Compares short-term and long-term volume momentum, exploring timescale contrast in volatility"
    },
    {
      "name": "vol_shape_normalised",
      "expression": "RANK($return) / TS_MAD($volume, 15)",
      "explanation": "Normalises return ranks by volume dispersion, exploring odd normalisation of signals"
    },
    {
      "name": "vol_order_statistic",
      "expression": "TS_ARGMAX($volume, 10) where $return < MEDIAN($return, 30)",
      "explanation": "Identifies extreme volume days with below-median returns, exploring order statistics in market states"
    },
    {
      "name": "vol_residual_weight",
      "expression": "REGRESI($return, SEQUENCE(10)) residual * TS_STD($volume, 10)",
      "explanation": "Weights volume volatility by return residuals, exploring residual analysis of market behavior"
    }
  ]
}

